// @FIGURE_CODE_BEGIN
(function () {
  var W = 900, H = 600;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%').viewbox(0, 0, W, H);
  var CX = 450, CY = 335, PXU = 75;          // world-unit -> px
  var CRIT_R = 2.52;                          // critical radius (model)
  var NU = 2.5, CAP = 0.6, LEAK_C = 0.84;     // physics model constants
  var N0 = 4;                                 // initiating neutron population

  // arrowhead marker
  var head = draw.marker(12, 12, function (add) { add.path('M0,0 L12,6 L0,12 z').fill('#111'); });
  head.attr({ refX: 9, refY: 6, orient: 'auto', markerWidth: 7, markerHeight: 7 });

  // static layers
  var titleTxt = draw.text('').font({ size: 26, weight: 'bold', family: 'sans-serif', anchor: 'middle' }).fill('#111').move(CX, 28);
  var captionTxt = draw.text('').font({ size: 20, family: 'sans-serif', anchor: 'middle' }).fill('#111').move(CX, 560);
  var escTxt = draw.text('').font({ size: 15, family: 'sans-serif', anchor: 'end' }).fill('#222').move(W - 24, 30);
  var genTxt = draw.text('').font({ size: 15, family: 'sans-serif', anchor: 'end' }).fill('#222').move(W - 24, 52);

  var scene = draw.group();   // rebuilt on every radius change
  var starEls = [];           // {el, gen}
  var R = 1.2;
  var chainState = 'idle';
  var running = false;

  function mulberry32(a) {
    return function () {
      a |= 0; a = a + 0x6D2B79F5 | 0;
      var t = Math.imul(a ^ a >>> 15, 1 | a);
      t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
      return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
  }

  function escapeFraction(r) { return Math.min(1, Math.max(0, LEAK_C / r)); }
  function multFactor(r) { return NU * (1 - escapeFraction(r)) * CAP; }

  function starburst(g, x, y, scale) {
    var pts = [], spikes = 12, ro = 11 * scale, ri = 4.2 * scale;
    for (var i = 0; i < spikes * 2; i++) {
      var ang = (Math.PI * i) / spikes - Math.PI / 2;
      var rr = (i % 2 === 0) ? ro : ri;
      pts.push([x + Math.cos(ang) * rr, y + Math.sin(ang) * rr]);
    }
    var poly = g.polygon(pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' '))
      .fill('#f3cf4a').stroke('#d8a900', 0.6);
    g.circle(5 * scale).center(x, y).fill('#fff7d6').attr({ opacity: 0.9 });
    return poly;
  }

  function render() {
    scene.clear();
    starEls = [];
    var Rpx = R * PXU;

    // fissile mass circle (muted periwinkle) + faint boundary emphasis
    scene.circle(2 * Rpx).center(CX, CY).fill('#8b93cf').attr({ opacity: 0.92 });
    scene.circle(2 * Rpx).center(CX, CY).fill('none').stroke('#5b63a8', 1.5).attr({ opacity: 0.6 });

    var rnd = mulberry32(1234 + Math.round(R * 100));
    var count = Math.max(4, Math.round(4 * R * R));

    // fission starbursts (uniform over area)
    var centers = [];
    for (var i = 0; i < count; i++) {
      var fa = rnd() * Math.PI * 2;
      var fr = Math.sqrt(rnd()) * 0.82 * Rpx;
      var sx = CX + Math.cos(fa) * fr, sy = CY + Math.sin(fa) * fr;
      centers.push([sx, sy]);
      var el = starburst(scene, sx, sy, 0.85 + 0.3 * rnd());
      el.on('mousemove', function (e) { showTooltip('Fission event: a nucleus splits, releasing neutrons.', e); })
        .on('mouseleave', hideTooltip).css('cursor', 'pointer');
      starEls.push({ el: el, gen: Math.floor(rnd() * 4) });
    }

    // neutron arrows from each fission site
    for (var j = 0; j < centers.length; j++) {
      var nArr = 1 + (rnd() < 0.6 ? 1 : 0);
      for (var k = 0; k < nArr; k++) {
        var aa = rnd() * Math.PI * 2;
        var len = 0.42 * Rpx;
        var x0 = centers[j][0], y0 = centers[j][1];
        var tx = x0 + Math.cos(aa) * len, ty = y0 + Math.sin(aa) * len;
        var dTip = Math.hypot(tx - CX, ty - CY);
        var escaped = dTip > Rpx;
        if (escaped) { // push tip clearly past the boundary
          var ux = (tx - CX) / dTip, uy = (ty - CY) / dTip;
          tx = CX + ux * (Rpx + 26); ty = CY + uy * (Rpx + 26);
        }
        var ln = scene.line(x0, y0, tx, ty).stroke({ color: '#111', width: 2, linecap: 'round' }).marker('end', head);
        ln.on('mousemove', function (e) {
          showTooltip(escaped ? 'Escaped neutron: leaks out through the surface (lost).' : 'Captured neutron: stays inside and can trigger a new fission.', e);
        }).on('mouseleave', hideTooltip);
      }
    }

    // initiating neutron (gray sphere, upper-left, inbound arrow)
    var ia = Math.PI * 0.78;
    var gx = CX + Math.cos(ia) * (Rpx + 34), gy = CY + Math.sin(ia) * (Rpx + 34);
    var ex = CX + Math.cos(ia) * (Rpx + 2), ey = CY + Math.sin(ia) * (Rpx + 2);
    scene.line(gx, gy, ex, ey).stroke({ color: '#111', width: 2.4, linecap: 'round' }).marker('end', head);
    var sph = scene.circle(16).center(gx, gy).fill('#cfcfcf').stroke('#9a9a9a', 1);
    sph.on('mousemove', function (e) { showTooltip('Initiating neutron that starts the chain reaction.', e); }).on('mouseleave', hideTooltip);

    updateLabels();
    applyChainVisual();
  }

  function updateLabels() {
    var sub = R < CRIT_R;
    titleTxt.text(sub ? 'Sub-critical mass' : 'Critical mass');
    captionTxt.text(sub ? '(a)' : '(b)');
    escTxt.text('Neutrons escaping: ' + Math.round(escapeFraction(R) * 100) + '%');
    if (chainState === 'idle') genTxt.text('Neutrons per generation: —');
  }

  function generations() {
    var m = multFactor(R), arr = [N0], n = N0;
    for (var g = 1; g <= 3; g++) { n = Math.round(n * m); arr.push(n); if (n === 0) break; }
    return arr;
  }

  function applyChainVisual() {
    var litGen = 3;
    if (chainState === 'idle') {
      starEls.forEach(function (s) { s.el.attr({ opacity: 1 }); });
      return;
    }
    var gens = generations();
    var lastSurv = 0;
    for (var i = 0; i < gens.length; i++) if (gens[i] > 0) lastSurv = i;
    if (chainState === 'done') litGen = lastSurv;
    starEls.forEach(function (s) { s.el.attr({ opacity: s.gen <= litGen ? 1 : 0.18 }); });
    genTxt.text('Neutrons per generation: ' + gens[Math.min(chainState === 'done' ? gens.length - 1 : currentGen, gens.length - 1)]);
  }

  var currentGen = 0;
  function trigger_chainReaction() {
    if (running) return;
    if (chainState === 'done') { chainState = 'idle'; currentGen = 0; document.getElementById('chainReactionBtn').textContent = 'Run chain reaction'; applyChainVisual(); updateLabels(); return; }
    running = true; chainState = 'run'; currentGen = 0;
    var gens = generations();
    document.getElementById('chainReactionBtn').textContent = 'Generation 0…';
    genTxt.text('Neutrons per generation: ' + gens[0]);
    starEls.forEach(function (s) { s.el.attr({ opacity: s.gen <= 0 ? 1 : 0.18 }); });
    var g = 0;
    (function step() {
      g++;
      if (g >= gens.length || gens[g] === 0) {
        chainState = 'done'; running = false;
        document.getElementById('chainReactionBtn').textContent = 'Reset';
        applyChainVisual();
        return;
      }
      currentGen = g;
      document.getElementById('chainReactionBtn').textContent = 'Generation ' + g + '…';
      genTxt.text('Neutrons per generation: ' + gens[g]);
      starEls.forEach(function (s) { s.el.attr({ opacity: s.gen <= g ? 1 : 0.18 }); });
      setTimeout(step, 650);
    })();
    setTimeout(step, 650);
  }

  function update_fissileMass(v) {
    R = v;
    if (chainState === 'run') { chainState = 'idle'; running = false; document.getElementById('chainReactionBtn').textContent = 'Run chain reaction'; }
    render();
  }
  window.update_fissileMass = update_fissileMass;
  window.trigger_chainReaction = trigger_chainReaction;

  // ---- guided demo steps ----
  var steps = [
    { title: 'Sub-critical: the chain dies', narration: 'At a small radius most emitted neutrons cross the boundary and escape, so each generation produces fewer surviving neutrons than the last. Step the chain reaction and watch the count collapse to zero.', state: { fissileMass: 1.2, chainReaction: 'done' } },
    { title: 'Growing the mass cuts leakage', narration: 'Drag the mass slider upward: the circle enlarges, fission sites become denser, and the escape-fraction readout drops because a smaller share of neutrons now reach the surface. Production begins to catch up with loss.', state: { fissileMass: 2.1, chainReaction: 'idle' } },
    { title: 'Critical: a self-sustaining chain', narration: 'At the critical radius most neutrons are captured and trigger further fissions; only a few escape. Step the chain reaction and the neutron count per generation holds steady or grows instead of dying out.', state: { fissileMass: 3, chainReaction: 'done' } }
  ];
  var stepIdx = -1;
  function applyStep(i) {
    stepIdx = i;
    document.getElementById('stepLabel').textContent = 'Step ' + (i + 1) + '/' + steps.length;
    document.getElementById('demoNarration').textContent = steps[i].narration;
    var st = steps[i].state;
    document.getElementById('fissileMassInput').value = st.fissileMass;
    document.getElementById('fissileMassVal').value = st.fissileMass;
    update_fissileMass(st.fissileMass);
    chainState = st.chainReaction; currentGen = 3; running = false;
    document.getElementById('chainReactionBtn').textContent = st.chainReaction === 'done' ? 'Reset' : 'Run chain reaction';
    applyChainVisual(); updateLabels();
  }
  window.nextStep = function () { applyStep(Math.min(steps.length - 1, stepIdx + 1)); };
  window.prevStep = function () { applyStep(Math.max(0, stepIdx - 1 < 0 ? 0 : stepIdx - 1)); };

  render();
  window.__markRendered();
})();
// @FIGURE_CODE_END

