// @FIGURE_CODE_BEGIN
(function () {
  var W = 900, H = 580;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%').viewbox(0, 0, W, H);

  // Panel geometry matching source proportions
  var PA = { cx: 205, cy: 295, r: 128 };
  var PB = { cx: 625, cy: 295, r: 188 };

  // Physics constants
  var CRIT_R = 2.52, NU = 2.5, CAP = 0.6, LEAK_C = 0.84;
  function escapeFraction(r) { return Math.min(1, Math.max(0, LEAK_C / r)); }

  // Arrowhead marker
  var head = draw.marker(12, 12, function (add) { add.path('M0,0 L12,6 L0,12 z').fill('#111'); });
  head.attr({ refX: 9, refY: 6, orient: 'auto', markerWidth: 6, markerHeight: 6 });

  // Seeded PRNG
  function mulberry32(a) {
    return function () {
      a |= 0; a = a + 0x6D2B79F5 | 0;
      var t = Math.imul(a ^ a >>> 15, 1 | a);
      t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
      return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
  }

  // Gold starburst
  function starburst(g, x, y, scale) {
    var pts = [], spikes = 10, ro = 13 * scale, ri = 4.8 * scale;
    for (var i = 0; i < spikes * 2; i++) {
      var ang = (Math.PI * i) / spikes - Math.PI / 2;
      var rr = (i % 2 === 0) ? ro : ri;
      pts.push([x + Math.cos(ang) * rr, y + Math.sin(ang) * rr]);
    }
    var poly = g.polygon(pts.map(function (p) { return p[0] + ',' + p[1]; }).join(' '))
      .fill('#f0c93a').stroke('#c9a200', 0.6);
    g.circle(5 * scale).center(x, y).fill('#fff8dc').attr({ opacity: 0.88 });
    return poly;
  }

  // Build one panel: circle, starbursts, arrows, gray sphere
  function buildPanel(panel, numStars, escRatio, seed) {
    var g = draw.group();
    var rnd = mulberry32(seed);

    // Periwinkle circle
    g.circle(2 * panel.r).center(panel.cx, panel.cy).fill('#8b93cf').attr({ opacity: 0.93 });
    g.circle(2 * panel.r).center(panel.cx, panel.cy).fill('none').stroke('#6a72b5', 1.4).attr({ opacity: 0.55 });

    // Place starbursts uniformly in area
    var centers = [];
    for (var i = 0; i < numStars; i++) {
      var fa = rnd() * Math.PI * 2;
      var fr = Math.sqrt(rnd()) * 0.76 * panel.r;
      centers.push([panel.cx + Math.cos(fa) * fr, panel.cy + Math.sin(fa) * fr]);
    }
    // Draw starbursts
    for (var i = 0; i < centers.length; i++) {
      var sc = 0.72 + 0.38 * rnd();
      starburst(g, centers[i][0], centers[i][1], sc);
    }

    // Arrows: from each star, 1-2 arrows; escRatio fraction escape
    for (var j = 0; j < centers.length; j++) {
      var nArr = 1 + (rnd() < 0.55 ? 1 : 0);
      for (var k = 0; k < nArr; k++) {
        var x0 = centers[j][0], y0 = centers[j][1];
        var escaped = rnd() < escRatio;
        var tx, ty;
        if (escaped) {
          // Point outward past boundary
          var oa = rnd() * Math.PI * 2;
          var tipR = panel.r + 22 + rnd() * 18;
          tx = panel.cx + Math.cos(oa) * tipR;
          ty = panel.cy + Math.sin(oa) * tipR;
          // Start from the star position
        } else {
          // Point toward nearest other starburst
          var best = -1, bestD = 1e9;
          for (var m = 0; m < centers.length; m++) {
            if (m === j) continue;
            var dd = Math.hypot(centers[m][0] - x0, centers[m][1] - y0);
            if (dd < bestD) { bestD = dd; best = m; }
          }
          if (best >= 0) {
            var dx = centers[best][0] - x0, dy = centers[best][1] - y0;
            var dl = Math.hypot(dx, dy);
            // Stop short of target
            tx = x0 + dx * 0.72;
            ty = y0 + dy * 0.72;
          } else {
            tx = x0 + 20; ty = y0;
          }
        }
        g.line(x0, y0, tx, ty).stroke({ color: '#111', width: 2.2, linecap: 'round' }).marker('end', head);
      }
    }

    // Gray initiating neutron sphere, upper-left outside
    var ia = -Math.PI * 0.72;
    var gx = panel.cx + Math.cos(ia) * (panel.r + 32);
    var gy = panel.cy + Math.sin(ia) * (panel.r + 32);
    var ex = panel.cx + Math.cos(ia) * (panel.r + 5);
    var ey = panel.cy + Math.sin(ia) * (panel.r + 5);
    g.line(gx, gy, ex, ey).stroke({ color: '#111', width: 2.4, linecap: 'round' }).marker('end', head);
    g.circle(15).center(gx, gy).fill('#c8c8c8').stroke('#999', 1.2);

    return g;
  }

  var panelA = buildPanel(PA, 10, 0.60, 42);
  var panelB = buildPanel(PB, 18, 0.25, 77);

  // Titles above
  draw.text('Sub-critical mass').font({ size: 21, weight: 'bold', family: 'sans-serif', anchor: 'middle' }).fill('#111').move(PA.cx - 60, 38);
  draw.text('Critical mass').font({ size: 21, weight: 'bold', family: 'sans-serif', anchor: 'middle' }).fill('#111').move(PB.cx - 55, 38);

  // Panel tags below
  draw.text('(a)').font({ size: 17, family: 'sans-serif', anchor: 'middle' }).fill('#111').move(PA.cx, 545);
  draw.text('(b)').font({ size: 17, family: 'sans-serif', anchor: 'middle' }).fill('#111').move(PB.cx, 545);

  // Morph overlay group (hidden initially)
  var morphG = draw.group().attr({ opacity: 0 });
  var morphCirc = morphG.circle(2 * PA.r).center(430, 295).fill('#8b93cf').attr({ opacity: 0.35 }).stroke('#222', 2.5).attr({ 'stroke-dasharray': '7,5' });
  var morphLabel = morphG.text('').font({ size: 15, weight: 'bold', family: 'sans-serif', anchor: 'middle' }).fill('#222').move(430, 510);
  var morphSub = morphG.text('').font({ size: 12, family: 'sans-serif', anchor: 'middle' }).fill('#444').move(430, 530);

  // Focus / dim logic
  var focusState = 'none';
  function setFocus(which) {
    focusState = which;
    panelA.attr({ opacity: which === 'b' ? 0.28 : 1 });
    panelB.attr({ opacity: which === 'a' ? 0.28 : 1 });
  }

  // Click-to-focus on panels
  panelA.css('cursor', 'pointer')
    .on('click', function () { setFocus(focusState === 'a' ? 'none' : 'a'); })
    .on('mousemove', function (e) { showTooltip('Panel (a): Sub-critical — most neutrons escape, chain dies out.', e); })
    .on('mouseleave', hideTooltip);
  panelB.css('cursor', 'pointer')
    .on('click', function () { setFocus(focusState === 'b' ? 'none' : 'b'); })
    .on('mousemove', function (e) { showTooltip('Panel (b): Critical — most neutrons captured, chain sustains.', e); })
    .on('mouseleave', hideTooltip);

  // Slider: morph highlight
  window.update_escapeFraction = function (v) {
    if (v <= 1.01) {
      morphG.attr({ opacity: 0 });
      return;
    }
    var frac = (v - 1) / 2; // 0..1
    var rPx = PA.r + (PB.r - PA.r) * frac;
    morphCirc.attr({ r: rPx });
    var ef = escapeFraction(v);
    var sub = v < CRIT_R;
    morphLabel.text('Escape fraction: ' + Math.round(ef * 100) + '%');
    morphSub.text(sub ? 'Sub-critical (r < r_crit)' : 'Critical / super-critical (r ≥ r_crit)');
    morphG.attr({ opacity: 1 });
  };

  // Neutron chain animation
  var animRunning = false;
  window.trigger_neutronAnimation = function () {
    if (animRunning) return;
    animRunning = true;
    // Sequentially flash starbursts in each panel
    var starsA = panelA.find('polygon');
    var starsB = panelB.find('polygon');
    var idxA = 0, idxB = 0;
    var maxGenA = 3, maxGenB = 6;
    var genA = 0, genB = 0;

    // Dim all first
    starsA.each(function () { this.attr({ opacity: 0.2 }); });
    starsB.each(function () { this.attr({ opacity: 0.2 }); });

    var timer = setInterval(function () {
      // Panel A: light up a few then stop (dies out)
      if (genA < maxGenA && idxA < starsA.length()) {
        var count = Math.max(1, Math.round(starsA.length() / maxGenA * (1 - genA * 0.3)));
        for (var i = 0; i < count && idxA < starsA.length(); i++, idxA++) {
          starsA.get(idxA).attr({ opacity: 1 });
        }
        genA++;
      }
      // Panel B: light up steadily (sustains)
      if (genB < maxGenB && idxB < starsB.length()) {
        var countB = Math.max(1, Math.round(starsB.length() / maxGenB));
        for (var i = 0; i < countB && idxB < starsB.length(); i++, idxB++) {
          starsB.get(idxB).attr({ opacity: 1 });
        }
        genB++;
      }
      if (genA >= maxGenA && genB >= maxGenB) {
        clearInterval(timer);
        animRunning = false;
        // Restore all after a pause
        setTimeout(function () {
          starsA.each(function () { this.attr({ opacity: 1 }); });
          starsB.each(function () { this.attr({ opacity: 1 }); });
        }, 1200);
      }
    }, 500);
  };

  // Demo steps
  var steps = [
    { title: 'Side-by-side comparison', narration: 'Both panels are shown: (a) a smaller sub-critical sample with many neutrons escaping the boundary, and (b) a larger critical sample where most neutrons are captured and trigger further fissions.', state: { escapeFraction: 1, focus: 'none' } },
    { title: 'Focus on sub-critical', narration: 'Panel (a) is highlighted. Notice the high density of outward-crossing arrows relative to internal ones — most neutrons escape before causing another fission, so the chain dies.', state: { escapeFraction: 1, focus: 'a' } },
    { title: 'Focus on critical', narration: 'Panel (b) is highlighted. The larger circle has a smaller surface-to-volume ratio: fewer arrows cross the boundary, and most terminate at interior fission sites, sustaining the chain.', state: { escapeFraction: 3, focus: 'b' } },
    { title: 'Morph between regimes', narration: 'The radius slider is set to 2 (between sub-critical and critical). Watch the escape-fraction overlay: the transition from dying to self-sustaining happens at a specific radius — the critical radius.', state: { escapeFraction: 2, focus: 'none' } }
  ];
  var stepIdx = 0;

  function applyStep(i) {
    stepIdx = i;
    document.getElementById('stepLabel').textContent = 'Step ' + (i + 1) + '/' + steps.length;
    document.getElementById('demoNarration').textContent = steps[i].narration;
    var st = steps[i].state;
    document.getElementById('escapeFractionInput').value = st.escapeFraction;
    document.getElementById('escapeFractionVal').value = st.escapeFraction;
    update_escapeFraction(st.escapeFraction);
    setFocus(st.focus || 'none');
  }
  window.nextStep = function () { applyStep(Math.min(steps.length - 1, stepIdx + 1)); };
  window.prevStep = function () { applyStep(Math.max(0, stepIdx - 1)); };

  // Initialize
  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

